def per(row):
    W=len(row)
    for p in range(1,W+1):
        if all(row[j]==row[j%p] for j in range(W)): return p
    return None
def f(g):
    return [[row[-per(r):+len(r)+len(row)-per(r)] for r in row] for row in g]
# simpler: build periodic extension to 2W
def f2(g):
    out=[]
    for row in g:
        W=len(row); p=per(row)
        ext=[row[j%p] for j in range(2*W)]
        out.append(ext)
    return out
